  ["7a34245fca7943d5"] = { "聞け、聞け！ここLakeshireで品物を売るのはほんの短い間だけだ。急いで町役場へ来てくれ！", "." },
  ["7a349eea8d790bb1"] = { "あなたは修行の頂点にほぼ達しました。最高の付呪師になるためには、あと1人訪ねるべき師がいます。彼女の名はAnnora、Uldamanで会えるでしょう。", "." },
  ["7a374449c1f3aa4a"] = { "Nagmara！マトンはまだ残ってるか？", "." },
  ["7a4a0f2e93147745"] = { "{name}！元気にしてたか、若いの？前に会ってから何を学んだか見せてみな。新しく教えられることがあるか見てやろう。", "." },
