  ["7a965f5177807890"] = { "オークションハウスはどこかって? なに、この素晴らしい街に入ってすぐ、Ironforgeの門のそばにあるさ。The Vaultの真向かいに見つかるよ。", "." },
  ["7a9c2ceb942e85d6"] = { "僕のパパは君のパパよりたくさん魚を釣れるんだぞ！", "." },
  ["7aaa68757b99f666"] = { "それは妙だな。", "." },
  ["7ab302d1872d155b"] = { "私がしてきたこと……なんと恐ろしいことを……\n\n<Tarsisはすすり泣き始める。>", "." },
  ["7abe00c543d45c00"] = { "集めた食糧と軍需物資は、すべてSilithusへ向かっている。一日もかからず着くはずだ。聞いた話じゃ、Cenarion Holdの近くに全部揃ったら、誰かがScarab Daisの銅鑼を鳴らしに行ってAhn'Qirajの門を開き、戦争を始めなきゃならないそうだ。", "." },
  ["7ac8e09c494cd076"] = { "私の時間を取るつもりなら、それだけの価値があると証明してもらわないとね。結局のところ、この取り決めで私も何か得なきゃならないんだから。", "." },
  ["7acb3cf1f156fe01"] = { "その後、彼女はどうなったんだ?", "." },
